table actors: CREATE TABLE actors (id text not null primary key, user text not null, domain text not null, handle text not null, network text not null, created integer not null, deleted integer not null default 0, key text not null default '')
table affiliations: CREATE TABLE affiliations (room text not null, address text not null, affiliation text not null, nick text not null default '', primary key (room, address))
table aliases: CREATE TABLE aliases (alias text not null primary key, room text not null, creator text not null, created integer not null)
table applications: CREATE TABLE applications (id text not null primary key, secret text not null default '', name text not null default '', website text not null default '', redirects text not null default '[]', scopes text not null default '', network text not null, created integer not null)
table backups: CREATE TABLE backups (user text not null, version integer not null, algorithm text not null, auth text not null, etag integer not null default 0, deleted integer not null default 0, primary key (user, version))
table blocked: CREATE TABLE blocked (actor text not null primary key, created integer not null)
table blocks: CREATE TABLE blocks (domain text not null primary key, created integer not null)
table bridges: CREATE TABLE bridges (room text not null primary key, user text not null, standin text not null, chat text not null default '', created integer not null)
table certificates: CREATE TABLE certificates (host text not null, issued integer not null)
table changes: CREATE TABLE changes (id integer primary key autoincrement, user text not null, viewer text not null default '', gone integer not null default 0, created integer not null)
table chatlog: CREATE TABLE chatlog (id integer primary key autoincrement, room text not null, archive text not null, nick text not null, sender text not null default '', stanza text not null, created integer not null)
table clients: CREATE TABLE clients (host text not null, network text not null, id text not null, secret text not null, redirect text not null default '', created integer not null, primary key (host, network))
table conferences: CREATE TABLE conferences (address text not null primary key, name text not null default '', description text not null default '', subject text not null default '', subjector text not null default '', persistent integer not null default 0, members integer not null default 0, public integer not null default 0, moderated integer not null default 0, open integer not null default 0, invite integer not null default 0, whois text not null default 'moderators', history integer not null default 20, locked integer not null default 0, created integer not null, updated integer not null)
table copies: CREATE TABLE copies (object text not null, account text not null, actor text not null, created integer not null, primary key (object, account, actor))
table data: CREATE TABLE data (user text not null, type text not null, content text not null, primary key (user, type))
table deliveries: CREATE TABLE deliveries (id text not null primary key, user text not null, account text not null, network text not null, inbox text not null, host text not null, body text not null, attempts integer not null default 0, next integer not null, claimed integer not null default 0, created integer not null, address text not null default '')
table destinations: CREATE TABLE destinations (name text not null primary key, failures integer not null default 0, retry integer not null default 0)
table devices: CREATE TABLE devices (user text not null, device text not null, name text not null default '', keys text not null default '', created integer not null, seen integer not null default 0, primary key (user, device))
table events: CREATE TABLE events (id text not null primary key, room text not null, type text not null, key text, membership text not null default '', sender text not null, depth integer not null, body text not null, rejected integer not null default 0, outlier integer not null default 0, redacted integer not null default 0, before integer not null default 0, received integer not null, replaces text)
table extremities: CREATE TABLE extremities (room text not null, event text not null, primary key (room, event))
table fallbacks: CREATE TABLE fallbacks (user text not null, device text not null, algorithm text not null, id text not null, key text not null, used integer not null default 0, primary key (user, device, algorithm))
table firehose: CREATE TABLE firehose (sequence integer not null primary key autoincrement, did text not null, kind text not null, body blob not null, created integer not null)
table hosts: CREATE TABLE hosts (host text not null primary key, failures integer not null default 0, success integer not null default 0, failure integer not null default 0, next integer not null default 0, error text not null default '')
table identities: CREATE TABLE identities (did text not null primary key, account text not null, user text not null, created integer not null)
table inbound: CREATE TABLE inbound (id text not null primary key, user text not null, account text not null, actor text not null, type text not null, body text not null, created integer not null)
table invites: CREATE TABLE invites (room text not null, user text not null, version text not null, sender text not null, body text not null, state text not null, created integer not null, primary key (room, user))
table keys: CREATE TABLE keys (name text not null primary key, algorithm text not null, public text not null, private text not null, created integer not null)
table media: CREATE TABLE media (id text not null primary key, domain text not null, user text not null, type text not null, name text not null default '', size integer not null default 0, created integer not null)
table messages: CREATE TABLE messages (id integer primary key autoincrement, user text not null, device text not null, sender text not null, type text not null, content text not null, created integer not null)
table occupants: CREATE TABLE occupants (room text not null, address text not null, nick text not null, bare text not null, role text not null, presence text not null default '', primary key (room, address))
table onetime: CREATE TABLE onetime (user text not null, device text not null, id text not null, key text not null, primary key (user, device, id))
table outbox: CREATE TABLE outbox (id integer primary key autoincrement, destination text not null, origin text not null default '', kind text not null, body text not null, created integer not null)
table pictrs: CREATE TABLE pictrs (file text not null primary key, user text not null, token text not null, type text not null, created integer not null)
table presence: CREATE TABLE presence (account text not null primary key, hidden integer not null default 0, shown text not null default '', told integer not null default 0)
table presences: CREATE TABLE presences (position integer primary key autoincrement, user text not null unique, presence text not null, message text not null default '', active integer not null default 0, updated integer not null)
table published: CREATE TABLE published (room text not null primary key, created integer not null)
table pushers: CREATE TABLE pushers (app text not null, key text not null, user text not null, primary key (app, key, user))
table receipts: CREATE TABLE receipts (position integer primary key autoincrement, room text not null, user text not null, type text not null, thread text not null default '', event text not null, ts integer not null, unique (room, user, type, thread))
table reports: CREATE TABLE reports (id text not null primary key, network text not null, reporter text not null, person text not null default '', user text not null default '', room text not null default '', objects text not null default '[]', category text not null default '', comment text not null default '', content text not null default '', names text not null default '{}', host text not null default '', created integer not null, resolved integer not null default 0, outcome text not null default '')
table retired: CREATE TABLE retired (domain text not null, key text not null, public text not null, expired integer not null, primary key (domain, key))
table rooms: CREATE TABLE rooms (id text not null primary key, version text not null, state integer not null default 0, created integer not null)
table secrets: CREATE TABLE secrets (name text not null primary key, value text not null)
table sent: CREATE TABLE sent (account text not null, key text not null, event text not null, created integer not null, primary key (account, key))
table servers: CREATE TABLE servers (name text not null, key text not null, public text not null, valid integer not null, expired integer not null default 0, primary key (name, key))
table sessions: CREATE TABLE sessions (user text not null, version integer not null, room text not null, session text not null, data text not null, primary key (user, version, room, session))
table signatures: CREATE TABLE signatures (user text not null, target text not null, signer text not null, id text not null, value text not null, primary key (user, target, signer, id))
table signing: CREATE TABLE signing (user text not null, purpose text not null, key text not null, primary key (user, purpose))
table snapshots: CREATE TABLE snapshots (id integer primary key autoincrement, room text not null, state text not null, base integer not null default 0, depth integer not null default 0)
table standins: CREATE TABLE standins (id text not null primary key, domain text not null, entity text not null, name text not null, avatar text not null default '', user text not null, created integer not null)
table stream: CREATE TABLE stream (position integer primary key autoincrement, room text not null, event text not null unique)
table subscribers: CREATE TABLE subscribers (topic text not null, callback text not null, secret text not null default '', expires integer not null, created integer not null, primary key (topic, callback))
table tokens: CREATE TABLE tokens (hash text not null primary key, client text not null, scopes text not null default '', created integer not null)
table topics: CREATE TABLE topics (topic text not null primary key, user text not null, app text not null, key text not null, created integer not null)
table transactions: CREATE TABLE transactions (origin text not null, id text not null, received integer not null, primary key (origin, id))
table uploads: CREATE TABLE uploads (id text not null primary key, user text not null, account text not null default '', domain text not null, name text not null, type text not null, size integer not null, token text not null default '', created integer not null, stored integer not null default 0)
table webmentions: CREATE TABLE webmentions (id integer primary key autoincrement, direction text not null, source text not null, target text not null, user text not null default '', app text not null default '', entity text not null default '', attempts integer not null default 0, next integer not null, created integer not null, unique (direction, source, target))
table websub: CREATE TABLE websub (id text not null primary key, user text not null, app text not null, source text not null, topic text not null, hub text not null, secret text not null, state text not null, expires integer not null default 0, attempts integer not null default 0, asked integer not null default 0, created integer not null, unique (user, app, source))
